1	export function applyDiscount(subtotalMinor, discount) {
2	  if (!discount) return subtotalMinor;
3	  if (discount.kind === "percent") return Math.round(subtotalMinor * (1 - discount.value / 100));
4	  if (discount.kind === "fixed") return Math.max(0, subtotalMinor - discount.valueMinor);
5	  throw new Error(`unknown discount ${discount.kind}`);
6	}
